INSERT INTO ap_traffic_logs (
    id_project,
    id_lokasi,
    ap_floor_id,
    nama_lantai,
    tanggal,
    traffic_value,
    traffic_unit,
    traffic_in_mb,
    jumlah_user,
    user_id,
    created_at,
    updated_at
)
SELECT
    @id_project,
    @id_lokasi,
    (
        SELECT af.id
        FROM ap_floors af
        WHERE af.id_lokasi = @id_lokasi
          AND (af.id_project = @id_project OR af.id_project IS NULL)
          AND UPPER(TRIM(af.nama_lantai)) = staged.nama_lantai
        ORDER BY CASE WHEN af.id_project = @id_project THEN 0 ELSE 1 END, af.id
        LIMIT 1
    ),
    staged.nama_lantai,
    STR_TO_DATE(CONCAT('2026-08-', LPAD(staged.hari, 2, '0')), '%Y-%m-%d'),
    CAST(LEFT(staged.traffic_raw, LENGTH(staged.traffic_raw) - 2) AS DECIMAL(12, 2)),
    RIGHT(staged.traffic_raw, 2),
    CASE RIGHT(staged.traffic_raw, 2)
        WHEN 'KB' THEN CAST(LEFT(staged.traffic_raw, LENGTH(staged.traffic_raw) - 2) AS DECIMAL(12, 2)) / 1024
        WHEN 'MB' THEN CAST(LEFT(staged.traffic_raw, LENGTH(staged.traffic_raw) - 2) AS DECIMAL(12, 2))
        WHEN 'GB' THEN CAST(LEFT(staged.traffic_raw, LENGTH(staged.traffic_raw) - 2) AS DECIMAL(12, 2)) * 1024
        WHEN 'TB' THEN CAST(LEFT(staged.traffic_raw, LENGTH(staged.traffic_raw) - 2) AS DECIMAL(12, 2)) * 1048576
    END,
    0,
    @user_id,
    NOW(),
    NOW()
FROM tmp_ap_traffic_august_2026 staged
ON DUPLICATE KEY UPDATE
    id_project = VALUES(id_project),
    ap_floor_id = VALUES(ap_floor_id),
    traffic_value = VALUES(traffic_value),
    traffic_unit = VALUES(traffic_unit),
    traffic_in_mb = VALUES(traffic_in_mb),
    jumlah_user = VALUES(jumlah_user),
    user_id = VALUES(user_id),
    updated_at = VALUES(updated_at);

COMMIT;

-- Expected import size: 19 floors x 31 days = 589 rows.
SELECT COUNT(*) AS imported_rows
FROM ap_traffic_logs
WHERE id_project <=> @id_project
  AND id_lokasi = @id_lokasi
  AND tanggal BETWEEN '2026-08-01' AND '2026-08-31'
  AND nama_lantai IN (
      'LANTAI 2', 'LANTAI 3', 'LANTAI 5', 'LANTAI 8', 'LANTAI 9',
      'LANTAI 18', 'LANTAI 26', 'LANTAI 27', 'LANTAI 28', 'LANTAI 29',
      'LANTAI 30', 'LANTAI 31', 'LANTAI 32', 'LANTAI 33', 'LANTAI 37',
      'LANTAI 38', 'LANTAI 39', 'LANTAI 40', 'LANTAI 41'
  );

DROP TEMPORARY TABLE tmp_ap_traffic_august_2026;
